-- GENERATED by `wfj generate` from data/gossip/gossip-7b.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["7b060d91eb130d3a"] = { "Ormai vai oltre ciò che posso insegnarti. Mettiti in viaggio verso il ⟦Aerie Peak=Picco dell'Aquila⟧, nelle Entroterre, e parla con il nano Drakk Stonehand. Il suo lavoro è magnifico, molto migliore del mio.", "." },
  ["7b0695855b880472"] = { "Mi sei mancato tanto, papà!", "." },
  ["7b08462537d05e0d"] = { "Parlami di Vanndar Stormpike.", "." },
  ["7b0edbdcd9fcf14f"] = { "Cos'hai fatto? FOLLE! L'hai portato... NO!", "." },
  ["7b0f8d28c2179ef5"] = { "Stolti! La nostra causa è giusta!", "." },
  ["7b14a58b16290a0f"] = { "⟦Razorfen Downs=Sotterranei di Lamaspina⟧", "." },
  ["7b186ac76a00d836"] = { "Mi allenerò e un giorno combatterò come mio padre!", "." },
  ["7b20b2ceade3ac83"] = { "Il tempo dell'allenamento è finito! Mostratemi cosa avete imparato!", "." },
  ["7b29224d11964b09"] = { "Proprio così, ehm, <ragazzo/ragazza>: tutto il materiale bellico viene trasportato a ⟦Silithus=Silitus⟧ e l'ultimo carico dovrebbe arrivare entro $2113w giorni. Dopo, non ci resterà che aspettare e vedere chi farà avanti <un/una> <eroe/eroina> per ricomporre lo Scettro delle Sabbie Mutevoli e suonare il gong sullo Scarab Dais. Solo allora la guerra aprirà le porte di ⟦Ahn'Qiraj=Ahn'qiraj⟧.", "." },
  ["7b2e9a199b225d66"] = { "Tu non ti unisci a nessuno, Thorsen..", "." },
  ["7b31f31f152737bd"] = { "Che le fiamme del caos ti avvolgano!", "." },
  ["7b3746a6fa1054a0"] = { "Ok, si parte!", "." },
  ["7b37b76d848b7700"] = { "Se ho da fare? Che cosa vorresti dire? Credi che stia qui tutto il giorno a girarmi i pollici? Se sei qui per comprare qualcosa, parla con Handor.", "." },
  ["7b3ea0b1ce0be3e9"] = { "E cosa ti ha portato a Naxxramas?", "." },
  ["7b4404a499e7d14c"] = { "Ci hai pensato, vero? Sei <un/una> {class} in gamba se accetti questo patto: tu e io avremo ciò che vogliamo entrambi, e Droffers and Son Salvage crederanno di avere ciò che vogliono loro.", "." },
  ["7b4b7418fe6a8683"] = { "Ahah! Perfetto!", "." },
  ["7b4c0c7cdecf3b44"] = { "L'⟦Argent Dawn=Alba d'Argento⟧ ti saluta, {class}. Sono Hasana, una dei pochi quartiermastri autorizzati per l'equipaggiamento e il materiale dell'Alba.\n\nMentre combatti il male su nostro incarico, guadagnandoti nel frattempo il nostro rispetto e la nostra fiducia, otterrai Emblemi del Valore dall'ufficiale Garush. Gli emblemi servono a due scopi: usali per migliorare la tua posizione nei nostri ranghi, oppure come moneta per acquistare oggetti speciali.\n\nMan mano che migliorerai la tua posizione presso l'Alba, scoprirai che avrai a disposizione sempre più oggetti.", "." },
  ["7b4f3c0bf43f3d21"] = { "Alla salute! Non troverai birra migliore da nessuna parte!", "." },
  ["7b4f8173efbdb30f"] = { "Stratholme non esiste più! La città è in rovina. Il principe, consumato dall'odio... dalla follia...", "." },
  ["7b5003550be4455f"] = { "L'animale sembra confuso.", "." },
  ["7b53fb83061b43fd"] = { "⟦Deeprun Tram=Tram degli Abissi⟧", "." },
  ["7b5441d14e73b729"] = { "Brandur Ironhammer è quello che fa per te. Lo trovi nella Hall of Mysteries, a nord dei cancelli di ⟦Ironforge=Forgiardente⟧.", "." },
  ["7b58d92700a36350"] = { "Come vuoi, signore.", "." },
  ["7b5e140b74a77a0b"] = { "Presto! Ti preeego, presto!!", "." },
  ["7b5ee9d512123753"] = { "Non troverai pace nella morte.", "." },
  ["7b660fc8deeac5ca"] = { "Ripensandoci... credo che passerò.", "." },
  ["7b6bc781b7f37f1a"] = { "Dopo ci siamo separati, ecco cos'è successo. Troppo rancore, immagino... covava da un po'. E la faccenda dell'amuleto è stata la paglia che ha spezzato la schiena al kodo.\n\nDa allora i servitori di Valthalak ci fanno fuori uno a uno. Quasi tutti quelli che custodivano un frammento dell'amuleto sono morti, con l'anima corrotta dalla parte dello spirito di Valthalak racchiusa al suo interno.\n\nEcco perché sono felice che tu sia qui, {name}. Con il tuo aiuto potremo ricomporre l'amuleto e restituirlo a lord Valthalak!", "." },
  ["7b73d6031d15798f"] = { "Il mio unico desiderio è servirti, o grande, finché non morirò sotto il tuo piede!", "." },
  ["7b7a24d9b92d90f2"] = { "Sei qui per imparare le pozioni? Ho un sacco di cose da insegnarti. Avrò anche tirato le cuoia, ma il cervello non l'ho perso. Non ancora.", "." },
  ["7b7af356f2bc0ca3"] = { "Non volevo offenderti con quella battuta sul fatto che sei <un/una> {class} stupid<o/a>. Siamo amici, giusto? Senza rancore?", "." },
  ["7b7b1d9c78ffa2a8"] = { "Forse stai inseguendo delle favole, {name}, ma anche nel cuore delle voci più assurde si può trovare la verità.", "." },
  ["7b7cdae795023d6f"] = { "Avete commesso un errore terribile e costoso. Non è ancora la mia ora, mortali.", "." },
  ["7b8b101cced7a9a2"] = { "La guarigione è per chi non sa sopportare il dolore. Ma se proprio devi, cerca la Spirit Lodge sul lago della ⟦Valley of Spirits=Valle degli Spiriti⟧, in alto, sopra la ⟦Valley of Strength=Valle della Forza⟧, verso ovest.", "." },
  ["7b8b2b3c0fe42039"] = { "Fai di questa locanda la mia casa.", "." },
  ["7b8d8beda8e60f80"] = { "Cerca Pala, che gestisce la locanda, nell'edificio appena a sud della banca di ⟦Thunder Bluff=Picco del Tuono⟧, sul terrazzo inferiore.", "." },
  ["7b8efbf16bf26d70"] = { "L'anziano Primestone ha trascorso molti anni nella Valle di Cristallo, a ⟦Silithus=Silitus⟧.", "." },
  ["7b9e35f83fde79b8"] = { "Attenzione! Attenzione! Allarme intrusi! Allarme intrusi!", "." },
  ["7ba42398c3cc7e9f"] = { "Aiuuutooo... co... costoole... rot... rotte.", "." },
  ["7ba8478828b74ca7"] = { "Siate benedetti, mortali, per questa liberazione... Hakkar non mi controlla più!", "." },
  ["7ba84beaab07c850"] = { "Oh, è semplicissimo! Lo usi come qualsiasi altra cosa che puoi attivare. Non preoccuparti, alla miccia penso io. Una volta in aria ti sembrerà di «galleggiare», ma non durerà per sempre. Devi puntare a un bersaglio sul lago, laggiù in fondo. Assicurati di iniziare la discesa staccando le tue «ali» al momento giusto per atterrare in acqua, altrimenti... beh, io non vendo assicurazioni sulla vita.", "." },
  ["7baa31162b33d927"] = { "Già, è proprio morto. Questo fa di te il nuovo re... beh, di tutti voi! Gordok adesso è vostro, capo! Parla con me, così impari tutto su come si fa il re! Io ero... sono il suo assistente! Già, è per questo che mi chiamano l'astuto!", "." },
  ["7bb0a3af9afb3482"] = { "Magar's Cloth Goods si trova al Varcolargo. Lo troverai a sud dell'enorme albero, accanto alla Kodohide Leatherworks.", "." },
  ["7bc3d82a8907b1be"] = { "Ma per ora, la tua morte dovrà bastare...", "." },
  ["7bc78265c401ee6d"] = { "Parlami delle torri.", "." },
  ["7bddf318009a865b"] = { "Hulfnar! Thontek! In piedi e rivolgetevi a me.", "." },
  ["7bdee48f052ffc84"] = { "Ehi, Harlan. Ecco un carico di stoffa a maglia per te.", "." },
  ["7be3fed15a2bd6bf"] = { "La tua presenza ci rinsalda i nervi, <signore/signora> {name}.", "." },
  ["7be7ada8de747b7e"] = { "Una spaccatura?", "." },
  ["7be8e1c7f2a0a949"] = { "Tutti i compiti dell'Orda per lo sforzo bellico sono completati, giovane {class}. Ora non resta che aspettare che anche l'⟦Alliance=Alleanza⟧ finisca i suoi, e tutto sarà pronto per la Guerra di ⟦Ahn'Qiraj=Ahn'qiraj⟧. Tranne forse la raccolta e la riunificazione dei frammenti dello Scettro delle Sabbie Mutevoli?", "." },
  ["7bea5b2a7663c206"] = { "Dalla pietra si ode un sussurro...\n\nSalute, <piccolo/piccola>. Hai notizie per il Templare?", "." },
  ["7bf0ee43ef6dfcd4"] = { "Studialo, {name}: il Catalogue of the Wayward.", "." },
  ["7bf848822f3e9cf0"] = { "Sia chiaro, <pivello/principessina>: non sono in vena di commenti che tu trovi carini o divertenti. Sono qui per assicurarmi che le ricerche dell'Arcidruido procedano come previsto, e ho l'ordine di eliminare tutti gli smidollati che non hanno la stoffa per servire nel mio amato ⟦Cenarion Circle=Circolo Cenariano⟧.", "." },
  ["7bfd3be8f4fd2450"] = { "%s colpisce in un lampo il bersaglio centrale, dritto nel mezzo...", "." },
  ["7bfe46be23dbff65"] = { "Sì, sì. Mmh, sembra rimandare a un altro tomo. Mi sa che devo trovare anche quello.", "." },
  ["7bfe9bfba6ec36f7"] = { "Dammi l'insegna #1!", "." },
  ["7bfe9c7ea6ec56d8"] = { "Dammi l'insegna #2!", "." },
  ["7bfe9d01a6ec76b9"] = { "Dammi l'insegna #3!", "." },
})
